217	    private Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to, String voidReason) {
218	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
219	        refuseClosed(sheetId, claim.getDueBy());
220	        roles.require(sheetId, user, switch (to) {
221	            case OPEN -> "open";
222	            case SETTLED, PENDING -> "settle";
223	            case VOID -> "void";
224	            case DRAFT, DELETED -> throw new IllegalStateException();
225	        });
226	        if (!claim.getStatus().canBecome(to)) {
227	            throw new ClaimStatusException(claim.getStatus(), to);
228	        }
229	        if (to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
230	            refuseVoidSettled(claim, sheetId, user);
231	        }
232	        if (to == ClaimStatus.VOID) {
233	            refuseVoidReason(sheetId, voidReason);
234	        }
235	        String reversed = to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED
236	                ? " reversed=" + show(claim.getSettledDue()) : "";
237	        if (to == ClaimStatus.VOID && !voidReason.isEmpty()) {
238	            reversed += " reason=" + voidReason;
239	        }
240	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
241	            throw new ClaimSettlerException("The user who opened a claim cannot settle it.");
242	        }
243	        if (to == ClaimStatus.SETTLED && user.equals(claim.getEditedBy())) {
244	            throw new ClaimSettlerException("The user who last edited a claim cannot settle it.");
245	        }
246	        if (to == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
247	            throw new ClaimDeferException("The claim is deferred until " + claim.getDeferredUntil() + ".");
248	        }
249	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
250	                .orElseThrow(PersonNotFoundException::new);
251	        if (to == ClaimStatus.OPEN) {
252	            refuseNoteless(claim, shownDue(claim, person));
253	        }
254	        Rollup.Snapshot before = rollup.take(sheetId);
255	        String number = claim.getNumber();
256	        if (to == ClaimStatus.OPEN) {
257	            number = sheets.nextClaimNumber(sheetId, claim.getDueBy());
258	            claim.setOpenedBy(user);
259	        }
260	        if (to == ClaimStatus.SETTLED) {
261	            BigDecimal figure = claim.isBound() ? claim.getStatedDue() : liveDue(claim, person);
262	            BigDecimal due = figure == null ? null : charged(claim, person, figure);
263	            refuseUnproved(claim, person, due);
264	            if (overLimit(sheetId, user, due)) {
265	                to = ClaimStatus.PENDING;
266	            } else {
267	                claim.setSettledDue(due);
268	            }
269	        }
270	        claim.setStatus(to);
271	        claim.setNumber(number);
272	        if (to == ClaimStatus.VOID) {
273	            claim.setVoidReason(voidReason.isEmpty() ? null : voidReason);
274	        }
275	        logStatus(claim, person, user);
276	        Claim updated = claims.saveAndFlush(claim);
277	        String event = switch (to) {
278	            case OPEN -> "CLAIM_OPENED";
279	            case PENDING -> "CLAIM_PENDING";
280	            case SETTLED -> "CLAIM_SETTLED";
281	            case VOID -> "CLAIM_VOIDED";
282	            case DRAFT, DELETED -> throw new IllegalStateException();
283	        };
284	        audit(event, updated, person, user, number, to == ClaimStatus.SETTLED ? dueField(updated) : reversed);
285	        if (to == ClaimStatus.SETTLED) {
286	            notifyWatchers(updated, person, user);
287	        }
288	        rollup.recordChanges(sheetId, user, before);
289	        return updated;
290	    }
