307	     *  sheet's today, and a claim in a closed period. */
308	    @Transactional
309	    public Claim restore(String sheetId, String user, long claimId) {
310	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
311	        refuseClosed(sheetId, claim.getDueBy());
312	        if (claim.getStatus() != ClaimStatus.DELETED) {
313	            throw new ClaimDeleteException("Only a DELETED claim can be restored; this one is " + claim.getStatus() + ".");
314	        }
315	        LocalDate deletedOn = claim.getStatusLog().stream()
316	                .filter(line -> line.getStatus() == ClaimStatus.DELETED)
317	                .map(StatusChange::getOn)
318	                .reduce((first, last) -> last)
319	                .orElse(null);
320	        if (deletedOn == null || !deletedOn.equals(sheets.today(sheetId))) {
321	            throw new ClaimDeleteException("A deleted claim can only be restored on the day it was deleted.");
322	        }
323	        return moveDeleted(sheetId, user, claim, ClaimStatus.DRAFT, "CLAIM_RESTORED");
324	    }
