432	     *  no statement (today's rates, grades and floor, the late charge on the sheet's today on top). Refused
433	     *  unless the claim is SETTLED and the user is a steward, and for a claim in a closed period. */
434	    @Transactional
435	    public Claim resettle(String sheetId, String user, long claimId) {
436	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
437	        refuseClosed(sheetId, claim.getDueBy());
438	        if (!roles.isSteward(sheetId, user)) {
