440	        }
441	        if (claim.getStatus() != ClaimStatus.SETTLED) {
442	            throw new ClaimResettleException("Only a SETTLED claim can be re-settled.");
443	        }
444	        Rollup.Snapshot before = rollup.take(sheetId);
445	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
446	                .orElseThrow(PersonNotFoundException::new);
447	        BigDecimal old = claim.getSettledDue();
448	        BigDecimal figure = liveDue(claim, person);
449	        BigDecimal due = null;
450	        if (figure != null) {
451	            Sheet sheet = sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new);
452	            LocalDate lateFrom = sheet.lateFrom(claim.getDueBy(), person.gradeOn(claim.getDate()), claim.getDate());
453	            due = claim.isCorrection() ? figure
454	                    : sheet.floored(figure.add(sheet.lateCharge(figure, lateFrom, claim.getDate())), claim.getDate());
455	        }
