package net.officefloor.hq.app.history;


/**
 * The versions of a sheet, its people, their claims, its rates, its periods, the statements taken, the
 * patrons named, the watches kept, the roles given and the delegations made: each change keeps the state it left the
 * row in, with the sheet's today when it was made, so the rows can be read back as of a date — as the
 * changes made while the sheet's today was on or before it left them, each row's latest such change by the
 * order they were made, a change made later not counting whatever its today.
 * Kept by the entities' listener once the change is written, in the same transaction.
 */
@Component
public class History {

    private final JdbcTemplate jdbc;
    private final JsonMapper json = JsonMapper.builder()
            .changeDefaultVisibility(v -> v.withVisibility(PropertyAccessor.ALL, Visibility.NONE)
                    .withVisibility(PropertyAccessor.FIELD, Visibility.ANY))
            .disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES)
            .build();

    public History(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    @PostPersist
    @PostUpdate
    public void saved(Object entity) {
        keep(entity, json.writeValueAsString(entity));
    }

    @PostRemove
    public void removed(Object entity) {
        keep(entity, null);
    }

    /** Keep the sheet's state now: for a change Hibernate does not see as an update of the sheet itself
     *  (its dated settings). */
    public void keep(Sheet sheet) {
        saved(sheet);
    }

    private void keep(Object entity, String state) {
        String sheetId;
        String entityId;
        if (entity instanceof Sheet sheet) {
            sheetId = sheet.getId();
            entityId = sheet.getId();
        } else if (entity instanceof Claim claim) {
            sheetId = claim.getSheetId();
            entityId = String.valueOf(claim.getId());
        } else if (entity instanceof Person person) {
            sheetId = person.getSheetId();
            entityId = String.valueOf(person.getId());
        } else if (entity instanceof Rate rate) {
            sheetId = rate.getSheetId();
            entityId = String.valueOf(rate.getId());
        } else if (entity instanceof Period period) {
            sheetId = period.getSheetId();
            entityId = String.valueOf(period.getId());
        } else if (entity instanceof Statement statement) {
            sheetId = statement.getSheetId();
            entityId = String.valueOf(statement.getId());
        } else if (entity instanceof Patron patron) {
            sheetId = patron.getSheetId();
            entityId = String.valueOf(patron.getId());
        } else if (entity instanceof Watch watch) {
            sheetId = watch.getSheetId();
            entityId = String.valueOf(watch.getId());
        } else if (entity instanceof SheetRole role) {
            sheetId = role.getSheetId();
            entityId = String.valueOf(role.getId());
        } else if (entity instanceof Delegation delegation) {
            sheetId = delegation.getSheetId();
            entityId = String.valueOf(delegation.getId());
        } else {
            throw new IllegalArgumentException("No history kept of " + entity.getClass());
        }
        LocalDate today = entity instanceof Sheet sheet ? sheet.getToday()
                : jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId).stream()
                        .filter(Objects::nonNull).findFirst().map(Date::toLocalDate).orElse(null);
        if (today == null) {
            return;
        }
        jdbc.update("INSERT INTO entity_version (sheet_id, kind, entity_id, recorded_on, state) VALUES (?, ?, ?, ?, ?)",
                sheetId, entity.getClass().getSimpleName(), entityId, Date.valueOf(today), state);
    }

    /** The sheet's rows of a kind as of a date, by id in the order first kept: each one's latest version made
     *  while the sheet's today was on or before it; none for a row removed then or not yet made. */
    public <T> Map<String, T> asOf(Class<T> type, String sheetId, LocalDate date) {
        Map<String, String> latest = new LinkedHashMap<>();
        jdbc.query("SELECT entity_id, state FROM entity_version WHERE sheet_id = ? AND kind = ? AND recorded_on <= ?"
                + " ORDER BY id", rs -> {
                    latest.put(rs.getString(1), rs.getString(2));
                }, sheetId, type.getSimpleName(), Date.valueOf(date));
        Map<String, T> rows = new LinkedHashMap<>();
        latest.forEach((id, state) -> {
            if (state != null) {
                rows.put(id, json.readValue(state, type));
            }
        });
        return rows;
    }

    /** The sheet's rows of a kind as of a date, in the order first kept. */
    public <T> List<T> listAsOf(Class<T> type, String sheetId, LocalDate date) {
        return List.copyOf(asOf(type, sheetId, date).values());
    }

    /** A row as of a date; none when it was not made by then, or removed. */
    public <T> Optional<T> findAsOf(Class<T> type, String sheetId, Object id, LocalDate date) {
        return Optional.ofNullable(asOf(type, sheetId, date).get(String.valueOf(id)));
    }
}
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class ClaimController {

    /** A claim as the screen shows it: the amount with two decimals, the date YYYY-MM-DD, no number unless opened,
     *  the due fixed when it was settled (none while its due is live)
     *  who opened it (none while a draft), whether its person's last statement bound it and the figure
     *  it bound (none while unbound, or when that was n/a), and the number a correction corrects (none
     *  otherwise), its status log, oldest first, and the date it is deferred until (none when never deferred), its proofs count,
     *  the user whose editor is open on it (none while unlocked), and whether it was added while its period
     *  was soft-closed, and the last day it was reminded (none when never), and its external reference (none when
     *  not given), and its tags, sorted, and its comments, in the order written. */
    public record ClaimView(long id, long personId, String amount, String date, String note,
            ClaimStatus status, String number, String settledDue, String openedBy, boolean stated,
            String statedDue, String corrects, String dueBy, List<StatusLine> statusLog, String deferredUntil,
            int proofs, String splitFrom, String lockedBy, boolean lateEntry,
            String remindedOn, String ref, List<String> tags, String voidReason,
            List<CommentLine> comments, Integer settleBatch) {

        public static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate().toString(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
                    claim.getCorrects(), claim.getDueBy().toString(),
                    claim.getStatusLog().stream().map(StatusLine::of).toList(),
                    claim.getDeferredUntil() == null ? null : claim.getDeferredUntil().toString(),
                    claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(),
                    claim.isLateEntry(),
                    claim.getRemindedOn() == null ? null : claim.getRemindedOn().toString(), claim.getRef(),
                    claim.getTags(), claim.getVoidReason(),
                    claim.getComments().stream().map(CommentLine::of).toList(), claim.getSettleBatch());
        }
    }

    /** A line of a claim's status log: the status, who changed it, the sheet's today then (YYYY-MM-DD), and
     *  the due it had then, two decimals (none when n/a). */
    public record StatusLine(ClaimStatus status, String by, String on, String due) {

        static StatusLine of(StatusChange change) {
            return new StatusLine(change.getStatus(), change.getBy(), change.getOn().toString(),
                    change.getDue() == null ? null : change.getDue().toPlainString());
        }
    }

    /** A comment on a claim: who wrote it, the sheet's today then (YYYY-MM-DD), and its text. */
    public record CommentLine(String by, String on, String text) {

        static CommentLine of(ClaimComment comment) {
            return new CommentLine(comment.getBy(), comment.getOn().toString(), comment.getText());
        }
    }

    /** A claim's fields; a missing date takes the sheet's today, a missing note is empty. A negative
     *  amount (a correction) names the number of the claim it corrects. */
    public record ClaimRequest(
            @NotNull @Digits(integer = 13, fraction = 2) BigDecimal amount,
            LocalDate date,
            @Size(max = 1000) String note,
            @Size(max = 220) String corrects,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user) {
        return ClaimView.of(service.remind(sheetId.trim(), user.trim(), claimId));
    }

    /** A comment's text. */
    public record CommentRequest(@Size(max = 1000) String text) {
    }

    /** Comment on a claim; an empty comment is refused. */
    @PostMapping("/claims/{claimId}/comments")
    public ClaimView comment(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid CommentRequest request) {
        return ClaimView.of(service.comment(sheetId.trim(), user.trim(), claimId,
                request.text() == null ? "" : request.text().trim()));
    }

    /** Re-settle a SETTLED claim at its figure today: a steward freezes it again. */
    @PostMapping("/claims/{claimId}/resettle")
    public ClaimView resettle(@PathVariable @NotBlank @Size(max = 200) String sheetId,
    /** A proof that is not allowed, or a settle or approval of an unproved claim above the proof threshold,
     *  is refused with the reason, for the screen to show. */
    @ExceptionHandler(ClaimProofException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> proofRefused(ClaimProofException e) {
        return Map.of("message", e.getMessage());
    }

    /** An open of a claim with an empty note above the note threshold is refused with the reason, for the
     *  screen to show. */
    @ExceptionHandler(ClaimNoteException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> noteRefused(ClaimNoteException e) {
        return Map.of("message", e.getMessage());
    }

    /** A split that is not allowed is refused with the reason, for the screen to show. */
    @ExceptionHandler(ClaimSplitException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> splitRefused(ClaimSplitException e) {
        return Map.of("message", e.getMessage());
    }

    /** A re-date that is not allowed is refused with the reason, for the screen to show. */
    @ExceptionHandler(ClaimRedateException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> redateRefused(ClaimRedateException e) {
        return Map.of("message", e.getMessage());
    }

    /** A re-settle that is not allowed is refused with the reason, for the screen to show. */
    @ExceptionHandler(ClaimResettleException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> resettleRefused(ClaimResettleException e) {
        return Map.of("message", e.getMessage());
    }

    /** A delete or restore that is not allowed is refused with the reason, for the screen to show. */
    @ExceptionHandler(ClaimDeleteException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> deleteRefused(ClaimDeleteException e) {
        return Map.of("message", e.getMessage());
    }

    /** A reminder that is not allowed is refused with the reason, for the screen to show. */
    @ExceptionHandler(ClaimRemindException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> remindRefused(ClaimRemindException e) {
        return Map.of("message", e.getMessage());
    }

    /** An empty comment is refused with the reason, for the screen to show. */
    @ExceptionHandler(ClaimCommentException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public Map<String, String> commentRefused(ClaimCommentException e) {
        return Map.of("message", e.getMessage());
    }
}

